def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    if v1 == 0:
        return None

    change = v2 - v1
    percentage_change = (change / v1) * 100

    return {
        "value": percentage_change,
        "trace": {
            "base_value_2018": v1,
            "comparison_value_2019": v2,
            "change": change,
            "change_ratio": change / v1,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percent"
            }
        }
    }
